from fastapi import FastAPI, Header, HTTPException

from app.auth import USERS, decode_token

app = FastAPI()


@app.get("/me")
def read_me(authorization: str = Header()):
    user_id = decode_token(authorization.removeprefix("Bearer "))
    if user_id is None or user_id not in USERS:
        raise HTTPException(status_code=401, detail="invalid token")
    return USERS[user_id]


@app.get("/orders")
def list_orders(authorization: str = Header()):
    user_id = decode_token(authorization.removeprefix("Bearer "))
    if user_id is None or user_id not in USERS:
        raise HTTPException(status_code=401, detail="invalid token")
    return {"user_id": user_id, "orders": []}

import jwt
from pydantic import BaseModel

SECRET_KEY = "change-me"


class User(BaseModel):
    id: int
    name: str
    is_active: bool = True


USERS = {1: User(id=1, name="mpyw"), 2: User(id=2, name="ghost", is_active=False)}


def decode_token(token: str) -> int | None:
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=["HS256"])
    except jwt.InvalidTokenError:
        return None
    return int(payload["sub"])

